INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261117-senate-dem-leader-fight', 'van-hollen-schumer-senate-democratic-leader-race-vote-timing', 'newsroom', 'news_story', 'congress', 'EDITORIAL_REVIEW', 0, 'Van Hollen says at least 15 Democrats back his bid to unseat Schumer and warns against an early leadership vote', 'The Maryland senator called the race for Senate majority leader wide open. The vote is set for Tuesday, Dec. 1, but Schumer allies have weighed moving it up.', 'Sen. Chris Van Hollen of Maryland is pressing his challenge to Chuck Schumer for leader of the incoming Senate Democratic majority, and said he would oppose any attempt to hold the caucus vote early, according to a Yahoo News report published Monday, Nov. 16.

## Counting votes

Van Hollen told Politico, in an interview released Monday, Nov. 16, that Schumer''s team was trying to cut short debate and that most senators want a fair and open process, Yahoo News reported. He said more than a dozen senators and senators-elect support him, a number he described as growing; the report put his support at 15 or more. Only four have endorsed him publicly, including Sen. Bernie Sanders and incoming Sen. Abdul El-Sayed. On Sunday, Nov. 15, he told ABC News the contest was wide open.

Schumer has said he has the votes to remain leader.

## When the vote happens

The leadership election is scheduled for Tuesday, Dec. 1, according to Puck News, as cited by Yahoo News. Puck reported that Schumer''s allies had considered moving it up to as early as the week of Nov. 16.

## Pressure from outside

Dozens of demonstrators rallied outside Van Hollen''s Baltimore office on Saturday, Nov. 14, urging Democrats to choose him over Schumer when the party takes control of the Senate in January, Democracy Now reported. Organizers pointed to the midterm results as a call for new leadership.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:12300:12374/full/pct:25/0/default.jpg', 'Rotunda ceiling, U.S. Capitol, Washington, D.C. (file). Photo: Carol M. Highsmith / Library of Congress (highsm.12374), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-17.sql', 8, 0, 'newsroom-assistant', '2026-11-17T10:50:00.000Z', '2026-11-17T10:50:00.000Z');
