INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261117-alaska-senate-52-votes', 'peltola-52-votes-short-majority-alaska-senate-sullivan-campaign', 'newsroom', 'news_story', 'elections', 'EDITORIAL_REVIEW', 0, 'Peltola is 52 votes short of a majority in Alaska''s Senate race as Sullivan''s campaign says it will wait for certification', 'Mary Peltola held 49.98% of first-choice votes late on Monday, Nov. 16. Overseas ballots can arrive through Wednesday, Nov. 18, and certification is targeted for Wednesday, Nov. 25.', 'Democrat Mary Peltola moved within 52 votes of an outright majority in Alaska''s U.S. Senate race in the latest unofficial count from the state Division of Elections, Newsweek reported early on Tuesday, Nov. 17.

## The numbers

Peltola had 141,637 first-choice votes, or 49.98%, to 130,162, or 45.93%, for Republican Sen. Dan Sullivan, a lead of 11,475 votes. A third candidate, Daniel J. Sullivan Jr., had 4,684. As of 9:52 p.m. Eastern time on Monday, Nov. 16, the Associated Press estimated 98% of the vote had been counted and had not called the race, according to Newsweek. If no candidate passes 50% of first-choice votes, Alaska''s ranked-choice tabulation decides the winner.

## Sullivan''s campaign responds

Sullivan''s campaign spokesman, Nate Adams, said on the afternoon of Monday, Nov. 16, that the campaign would let the count run until certification and would not comment on individual ballot updates or projections, Newsweek reported. He said the campaign would have more to say by the end of the week.

## What comes next

Overseas ballots can arrive through Wednesday, Nov. 18. The ranked-choice tabulation is scheduled for the same day as the final count of absentee and questioned ballots, and certification is targeted for Wednesday, Nov. 25, according to Newsweek. Democrats also won Alaska''s governorship, with Jonathan Kreiss-Tomkins becoming the first Democrat to win the office since 1998, Democracy Now reported.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:04400:04432/full/pct:25/0/default.jpg', 'Mural, Juneau, Alaska (file). Photo: Carol M. Highsmith / Library of Congress (highsm.04432), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-17.sql', 8, 0, 'newsroom-assistant', '2026-11-17T10:50:00.000Z', '2026-11-17T10:50:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261117-alaska-senate-52-votes-src1', 'bd-20261117-alaska-senate-52-votes', 'Dan Sullivan Breaks Silence as Alaska Senate Race Nears Showdown', 'https://www.newsweek.com/dan-sullivan-breaks-silence-as-alaska-senate-race-nears-showdown-12725062', 'Newsweek', 'web', 'ATTRIBUTED_REPORT', 1, 1, '2026-11-17T10:50:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-17. Editor to confirm.', 'newsroom-assistant', '2026-11-17T10:50:00.000Z');
