INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261117-scotus-thomas-implicit-bias', 'supreme-court-declines-california-implicit-bias-maryland-gun-cases-thomas', 'newsroom', 'news_story', 'courts', 'EDITORIAL_REVIEW', 0, 'Supreme Court turns away challenges to California''s implicit-bias training rule and Maryland''s gun limits, with Thomas writing in both', 'In its order list of Monday, Nov. 16, the court denied review in both cases. Justice Thomas, joined by Justice Alito, dissented in the California case and flagged doubts about Maryland''s "sensitive place" rules.', 'The Supreme Court declined on Monday, Nov. 16, to hear a challenge to California''s requirement that continuing medical education courses address implicit bias, according to the court''s published order list. Justice Clarence Thomas, joined by Justice Samuel Alito, dissented, and Justice Neil Gorsuch said he would have granted review.

## The California case

The case, Khatibi v. Yip, was brought against the president of the Medical Board of California. The Ninth Circuit treated the training requirement as government speech. In his dissent, Thomas said he would have taken the case to clarify the government-speech doctrine and the three-factor test the court laid out in Shurtleff v. Boston in 2022, a case that began over a flag-raising at Boston City Hall.

## Maryland''s gun limits

In a second case, Novotny v. Moore, the court denied review of a challenge to Maryland''s restrictions on carrying guns in "sensitive places." Thomas wrote a statement agreeing with the denial because the challenge covered many distinct laws. He questioned whether several of the restrictions fit the nation''s historical tradition of firearm regulation and suggested a narrower case may deserve review.

## Other orders

The court also sent two cases back to lower courts for another look in light of decisions it issued earlier in 2026: Casarez v. Irigoyen Farms, from a California appeals court, and Huffman v. United States, from the Fifth Circuit.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:12500:12515/full/pct:25/0/default.jpg', 'Interior of the U.S. Supreme Court, Washington, D.C. (file). Photo: Carol M. Highsmith / Library of Congress (highsm.12515), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-17.sql', 7, 0, 'newsroom-assistant', '2026-11-17T10:50:00.000Z', '2026-11-17T10:50:00.000Z');
INSERT OR IGNORE INTO story_sources (id, story_id, title, url, publisher, channel, rights_type, verified, public, retrieved_at, notes, added_by, created_at) VALUES ('bd-20261117-scotus-thomas-implicit-bias-src1', 'bd-20261117-scotus-thomas-implicit-bias', 'Order List (11/16/2026)', 'https://www.supremecourt.gov/orders/courtorders/111626zor_cb7d.pdf', 'Supreme Court of the United States', 'web', 'PRIMARY_SOURCE', 1, 1, '2026-11-17T10:50:00.000Z', 'Opened and checked by the newsroom assistant on 2026-11-17. Editor to confirm.', 'newsroom-assistant', '2026-11-17T10:50:00.000Z');
