INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261117-measles-elimination-status', 'us-loses-measles-elimination-status-paho-5412-cases', 'newsroom', 'news_story', 'policy', 'EDITORIAL_REVIEW', 0, 'The U.S. is losing its measles elimination status after 26 years as cases pass 5,400 and deaths reach 10', 'A Pan American Health Organization commission concluded that measles is again spreading continuously in the country. The CDC counts 5,412 cases in 2026, the most since 1991.', 'The United States is losing the measles elimination status it has held for 26 years after a regional verification commission of the Pan American Health Organization concluded that endemic transmission has been reestablished, Latin Times reported on Sunday, Nov. 15, citing KFF Health News. PAHO had scheduled a public announcement for Tuesday, Nov. 17, and The Fulcrum reported on Nov. 17 that PAHO is stripping the status. Democracy Now reported on Monday, Nov. 16, that the status had been revoked.

## The numbers

The CDC counted 5,412 confirmed measles cases nationally as of Nov. 12, the highest total since 1991 and more than double the 2,289 cases reported in all of 2025. Pennsylvania alone had 1,542 cases as of Nov. 13, according to Latin Times. The CDC''s official tally lists six deaths in 2026, while state reports put the total at 10, with seven in Pennsylvania, two in Wisconsin and one in New York. The Fulcrum, citing The Washington Post, reported that half of those deaths came in the first two weeks of November and that 96% of infections were among unvaccinated people.

## How it happened

The 12-month clock began with a case in West Texas with a rash onset on Jan. 20, 2025. Transmission then spread to Utah, Arizona, South Carolina and dozens of other states, Latin Times reported. Kindergarten coverage for the measles, mumps and rubella vaccine was 92.4% for the 2025-26 school year, and 39 states were below the 95% target.

## The response

An HHS spokesperson attributed the resurgence to vaccination gaps that predated the current administration and denied that the department suppressed measles information, according to Latin Times. CDC Director Erica Schwartz said vaccination, not the designation, is what protects Americans, The Fulcrum reported. The American Public Health Association blamed HHS leadership. Democracy Now noted that the outbreak has grown as HHS Secretary Robert F. Kennedy Jr. has backed anti-vaccine policies.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:11000:11029/full/pct:25/0/default.jpg', '"Zones of Change" artwork at the Edward R. Roybal Building, Centers for Disease Control and Prevention campus, Atlanta (file). Photo: Carol M. Highsmith / Library of Congress (highsm.11029), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-17.sql', 7, 0, 'newsroom-assistant', '2026-11-17T10:50:00.000Z', '2026-11-17T10:50:00.000Z');
