INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261117-magic-celtics', 'magic-115-celtics-105-orlando-ends-boston-six-game-win-streak', 'newsroom', 'news_story', 'nba', 'EDITORIAL_REVIEW', 0, 'Magic 115, Celtics 105: Orlando wins the fourth quarter 40-28 and ends Boston''s six-game winning streak', 'Desmond Bane scored 24 for the Magic at TD Garden on Monday, Nov. 16. Jayson Tatum had 24 points and 12 rebounds a night after Boston beat Dallas.', 'The Orlando Magic pulled away late to beat the Celtics 115-105 at TD Garden on Monday, Nov. 16, ending Boston''s six-game winning streak, NBC Sports Boston and The Boston Globe reported. Boston entered the game 11-2 and atop the Eastern Conference, according to Yahoo Sports.

## How it turned

Boston led 82-78 early in the fourth quarter before Orlando ran off nine straight points while Tatum was on the bench, the Globe reported. Second-chance points did much of the damage, including two Magic 3-pointers that followed offensive rebounds. Orlando outscored Boston 40-28 in the quarter and led 104-99 with 3:16 left before Bane''s scoring, plus a Wendell Carter Jr. alley-oop, pushed the margin to 11, according to NBC Sports Boston.

## The numbers

Bane led Orlando with 24 points, Franz Wagner added 21 and Anthony Black had 20, NBC Sports Boston reported. The Magic played without Paolo Banchero, who was out with an ankle injury, according to Yahoo Sports. Tatum finished with 24 points and 12 rebounds on 9-of-23 shooting with five turnovers. Paul George scored 22 and Payton Pritchard 21. Boston made 9 of 17 free throws, and center Neemias Queta sat out to rest, the Globe reported.

## Up next

The loss came the night after Boston beat Dallas on Sunday, Nov. 15. The Celtics host Denver on Wednesday, Nov. 18, according to Yahoo Sports.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:57300:57307/full/pct:25/0/default.jpg', 'Aerial view of Boston highways and roads (file). Photo: Carol M. Highsmith / Library of Congress (highsm.57307), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-17.sql', 8, 0, 'newsroom-assistant', '2026-11-17T10:50:00.000Z', '2026-11-17T10:50:00.000Z');
