INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261117-chargers-ravens', 'chargers-23-ravens-20-los-angeles-first-win-monday-night-football', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Chargers 23, Ravens 20: Los Angeles holds on in Baltimore for its first win of the season', 'Omarion Hampton ran for 105 yards and Cam Hart broke up Jacoby Brissett''s last pass at the 4-yard line on Monday Night Football, Nov. 16.', 'The Los Angeles Chargers won for the first time this season, beating the Baltimore Ravens 23-20 at M&T Bank Stadium on Monday, Nov. 16, ESPN reported. The win moved the Chargers to 1-8.

## How Los Angeles won

The Chargers scored on their opening possession and never trailed. Their defense forced three-and-outs on Baltimore''s first three drives, and the offense scored on two of its first three, according to ESPN. Omarion Hampton ran for 105 yards on 22 carries as Los Angeles piled up a season-high 160 rushing yards. Justin Herbert threw just 18 passes, a season low, but ran for 51 yards, including a 22-yard touchdown. Los Angeles did not turn the ball over for the first time this season.

## The finish

With 2:03 left, Tarheeb Still forced a fumble by Zay Flowers and Elijah Molden recovered at the Chargers'' 46. Los Angeles could not pick up the first down that would have ended the game, and Baltimore got one more chance. Cam Hart knocked down Brissett''s final pass at the Chargers'' 4-yard line, ESPN reported.

## Baltimore''s night

Brissett threw for 340 yards in his first start since Baltimore acquired him in a trade. The Ravens'' running game was held to a season-low 16 yards, with Derrick Henry gaining 10 yards on 10 carries, according to ESPN.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:highsm:04800:04854/full/pct:25/0/default.jpg', 'Aerial view of the Camden Yards stadium complex, Baltimore, Maryland (file). Photo: Carol M. Highsmith / Library of Congress (highsm.04854), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-17.sql', 7, 0, 'newsroom-assistant', '2026-11-17T10:50:00.000Z', '2026-11-17T10:50:00.000Z');
