INSERT OR IGNORE INTO stories (id, slug, lane, type, section_slug, status, sensitive, headline, dek, body, byline, hero_image_url, hero_image_credit, hero_image_rights, source_system, source_ref, priority, is_lead_candidate, created_by, created_at, updated_at) VALUES ('bd-20261117-maye-ankle', 'patriots-fear-drake-maye-fractured-ankle-out-indefinitely-devito', 'newsroom', 'news_story', 'nfl', 'EDITORIAL_REVIEW', 0, 'Patriots fear Drake Maye fractured his ankle in Munich, and the quarterback is out indefinitely', 'Maye stayed in Germany for more tests after the loss to Detroit on Sunday, Nov. 15. New England is 5-5 and has its bye week next, with Tommy DeVito the top backup.', 'The New England Patriots fear quarterback Drake Maye fractured his ankle in the loss to the Detroit Lions in Munich on Sunday, Nov. 15, and he is out indefinitely, possibly for the rest of the season, according to ESPN reporting cited by CBS Sports. NFL Network reported that Maye suffered a significant lower-leg injury that could keep him out for an extended period.

## What happened

Maye was hurt on the last snap of New England''s opening drive, when Lions defensive lineman Aidan Hutchinson sacked him on third down, CBS Sports and WCVB reported. He limped off, went to the locker room and was ruled out.

## What Vrabel said

Coach Mike Vrabel said on WEEI''s Greg Hill Show on the morning of Monday, Nov. 16, that Maye stayed in Germany as a precaution and would travel back once it was confirmed he could do so safely, Yahoo Sports reported. Vrabel said the team would see what the tests showed. The extra testing is meant to determine whether Maye needs surgery, according to CBS Sports.

## Who plays quarterback

Tommy DeVito, the top backup, finished the game, completing 12 of 24 passes for 81 yards with a touchdown and an interception, CBS Sports reported. DeVito, 28, is 3-5 in eight career starts. Sports Illustrated reported that rookie Behren Morton is also expected to see time.

## Where New England stands

The Patriots are 5-5 after losing three of their last four and hold the eighth spot in the AFC playoff picture, according to CBS Sports. Maye had thrown for 2,330 yards, 18 touchdowns and a career-high 11 interceptions in 10 starts. New England has a bye in Week 11.', 'Boston Daily Staff', 'https://tile.loc.gov/image-services/iiif/service:pnp:ggbain:10900:10969/full/pct:25/0/default.jpg', 'Otis Love Guernsey, a Yale University football player, early 1900s (file). Photo: Bain News Service / Library of Congress (ggbain.10969), no known restrictions', 'public_domain', 'newsroom', 'content/2026-11-17.sql', 8, 0, 'newsroom-assistant', '2026-11-17T10:50:00.000Z', '2026-11-17T10:50:00.000Z');
